using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace BF4Bots {public static class FriendsTests {
 public static void Run(){var invite=new LanInvite{Version=1,Host="192.168.1.20",Leader="Líder",ExpiresUtc=DateTime.UtcNow.AddHours(1)};if(LanInvite.Decode(invite.Encode()).Leader!="Líder")throw new Exception("Convite não preserva identidade.");foreach(string bad in new[]{"127.0.0.1","0.0.0.0","8.8.8.8","192.168.1.20\r\nX=Y","http://192.168.1.20","::1"})if(Friends.PrivateIP(bad))throw new Exception("IP de convite indevido.");bool rejected=false;try{LanInvite.Decode("{\"Version\":1,\"Host\":\"192.168.1.20\",\"Leader\":\"a\"}");}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Convite sem validade aceito.");rejected=false;invite.ExpiresUtc=DateTime.UtcNow.AddMinutes(-1);try{invite.Encode();}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Convite expirado aceito.");
  var people=new List<PartyPlayer>{new PartyPlayer{Name="Host",Team=1,Squad=3},new PartyPlayer{Name="Amigo",Team=2,Squad=2},new PartyPlayer{Name="Bot",Team=2,Squad=2}};int moves=0;Func<string[],string[]> command=words=>{if(words[0]=="admin.listPlayers")return Serialize(people);if(words[0]!="admin.movePlayer"||words.Length!=5||words[4]!="false")throw new Exception("Comando de grupo indevido ou morte forçada.");var player=people.Single(p=>p.Name==words[1]);if(player.Name=="Bot")throw new Exception("Moveu jogador fora do grupo.");player.Team=Int32.Parse(words[2]);player.Squad=Int32.Parse(words[3]);moves++;return new[]{"OK"};};
  string status=Friends.Reconcile(command,"Host",new[]{"Amigo"});if(!status.StartsWith("Grupo reunido")||moves!=1)throw new Exception("Não reuniu o grupo.");Friends.Reconcile(command,"Host",new[]{"Amigo"});if(moves!=1)throw new Exception("Moveu grupo já reunido.");people[0].Team=2;people[0].Squad=4;Friends.Reconcile(command,"Host",new[]{"Amigo"});if(moves!=2||people[1].Team!=2||people[1].Squad!=4)throw new Exception("Não acompanhou troca de time/pelotão.");people[0].Squad=0;Friends.Reconcile(command,"Host",new[]{"Amigo"});if(people[0].Squad!=32||people[1].Squad!=32)throw new Exception("Não escolheu pelotão vazio.");
  people.Clear();people.Add(new PartyPlayer{Name="Host",Team=1,Squad=1});for(int i=0;i<4;i++)people.Add(new PartyPlayer{Name="Outro"+i,Team=1,Squad=1});moves=0;status=Friends.Reconcile(command,"Host",new[]{"Ausente"});if(moves!=0||!status.Contains("sem espaço"))throw new Exception("Ignorou capacidade do pelotão.");people.Clear();status=Friends.Reconcile(command,"Host",new[]{"Ausente"});if(!status.StartsWith("Aguardando"))throw new Exception("Host ausente não aguardou.");
  people.Add(new PartyPlayer{Name="Host",Team=1,Squad=1});people.Add(new PartyPlayer{Name="Host",Team=1,Squad=1});rejected=false;try{Friends.Players(Serialize(people));}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Nomes duplicados aceitos.");rejected=false;try{Friends.Players(new[]{"OK","3","name","teamId","squadId","2","Host","1","1"});}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Resposta truncada aceita.");
  people=new List<PartyPlayer>{new PartyPlayer{Name="Host",Team=1,Squad=1},new PartyPlayer{Name="Amigo",Team=2,Squad=2}};status=Friends.Reconcile(words=>words[0]=="admin.listPlayers"?Serialize(people):new[]{"OK"},"Host",new[]{"Amigo"});if(status.StartsWith("Grupo reunido"))throw new Exception("Confirmou movimento sem readback.");
 }
 static string[] Serialize(List<PartyPlayer> people){var words=new List<string>{"OK","4","guid","squadId","name","teamId",people.Count.ToString()};foreach(var p in people)words.AddRange(new[]{"fixture",p.Squad.ToString(),p.Name,p.Team.ToString()});return words.ToArray();}
}}
